// 🌸 Sakura (behind chat)
if (!parent.document.querySelector('.sakura-layer-v2')) {
  var html = '';
  html += '<div class="sakura-glow sakura-glow-top"></div>';
  html += '<div class="sakura-glow sakura-glow-bottom"></div>';
  html += '<div class="sakura-layer-v2">';
  for (var i = 1; i <= 18; i++) {
    var color = ['sakura-pink','sakura-white','sakura-rose','sakura-pale'][i % 4];
    html += '<div class="sakura-petal ' + color + ' sp-' + i + '"></div>';
  }
  html += '</div>';

  var css = document.createElement('style');
  css.id = 'sakura-v2-styles';
  css.textContent = ''
    + '.sakura-layer-v2{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;overflow:hidden}'
    + '.sakura-petal{position:absolute;top:-30px;pointer-events:none;width:12px;height:12px;opacity:0}'
    + '.sakura-petal::before{content:"";display:block;width:100%;height:100%;border-radius:50% 0 50% 50%;transform:rotate(-45deg)}'
    + '.sakura-pink::before{background:radial-gradient(ellipse,rgba(255,183,197,0.9),rgba(255,150,170,0.3))}'
    + '.sakura-white::before{background:radial-gradient(ellipse,rgba(255,245,250,0.9),rgba(255,220,230,0.3))}'
    + '.sakura-rose::before{background:radial-gradient(ellipse,rgba(255,160,180,0.85),rgba(240,130,160,0.3))}'
    + '.sakura-pale::before{background:radial-gradient(ellipse,rgba(255,210,220,0.9),rgba(255,190,210,0.3))}'
    + '.sakura-glow{position:fixed;pointer-events:none;z-index:0}'
    + '.sakura-glow-top{top:0;left:0;right:0;height:60px;background:linear-gradient(to bottom,rgba(255,180,200,0.06),transparent)}'
    + '.sakura-glow-bottom{bottom:0;left:0;right:0;height:60px;background:linear-gradient(to top,rgba(255,180,200,0.04),transparent)}'
    + '@keyframes sakura-fall{0%{transform:translateY(-30px) translateX(0) rotate(0deg) scale(1);opacity:0}'
    + '8%{opacity:0.9}50%{transform:translateY(50vh) translateX(var(--sx)) rotate(180deg) scale(0.9)}'
    + '100%{transform:translateY(108vh) translateX(var(--ex)) rotate(var(--spin));opacity:0}}'
    + '@keyframes sakura-sway{0%,100%{margin-left:0}50%{margin-left:var(--sway)}}'
    + '.sakura-petal{animation:sakura-fall var(--dur) ease-in infinite var(--del),sakura-sway 3s ease-in-out infinite}'
    + '.sp-1{left:2%;--dur:10s;--del:0s;--sx:40px;--ex:60px;--spin:320deg;--sway:8px}'
    + '.sp-2{left:7%;--dur:13s;--del:1.2s;--sx:-30px;--ex:-50px;--spin:400deg;--sway:-6px}'
    + '.sp-3{left:13%;--dur:11s;--del:3s;--sx:25px;--ex:35px;--spin:350deg;--sway:10px}'
    + '.sp-4{left:19%;--dur:9s;--del:0.5s;--sx:-40px;--ex:-60px;--spin:380deg;--sway:-8px}'
    + '.sp-5{left:25%;--dur:14s;--del:2.2s;--sx:20px;--ex:45px;--spin:300deg;--sway:7px}'
    + '.sp-6{left:31%;--dur:12s;--del:4.5s;--sx:-25px;--ex:-40px;--spin:420deg;--sway:-5px}'
    + '.sp-7{left:37%;--dur:8.5s;--del:1.8s;--sx:50px;--ex:70px;--spin:360deg;--sway:12px}'
    + '.sp-8{left:43%;--dur:13.5s;--del:3.5s;--sx:-15px;--ex:-30px;--spin:340deg;--sway:-9px}'
    + '.sp-9{left:49%;--dur:10.5s;--del:0.8s;--sx:30px;--ex:50px;--spin:390deg;--sway:6px}'
    + '.sp-10{left:55%;--dur:11.5s;--del:2.8s;--sx:-35px;--ex:-55px;--spin:370deg;--sway:-7px}'
    + '.sp-11{left:61%;--dur:9.5s;--del:5s;--sx:45px;--ex:65px;--spin:410deg;--sway:11px}'
    + '.sp-12{left:67%;--dur:12.5s;--del:1.5s;--sx:-20px;--ex:-35px;--spin:330deg;--sway:-10px}'
    + '.sp-13{left:73%;--dur:10s;--del:3.8s;--sx:35px;--ex:55px;--spin:380deg;--sway:8px}'
    + '.sp-14{left:78%;--dur:8s;--del:0.3s;--sx:-45px;--ex:-70px;--spin:400deg;--sway:-6px}'
    + '.sp-15{left:83%;--dur:14.5s;--del:2.5s;--sx:15px;--ex:25px;--spin:350deg;--sway:9px}'
    + '.sp-16{left:88%;--dur:11s;--del:4.8s;--sx:-30px;--ex:-45px;--spin:360deg;--sway:-8px}'
    + '.sp-17{left:93%;--dur:9s;--del:1s;--sx:40px;--ex:55px;--spin:310deg;--sway:7px}'
    + '.sp-18{left:96%;--dur:13s;--del:3.2s;--sx:-25px;--ex:-40px;--spin:390deg;--sway:-5px}'
  ;
  parent.document.head.appendChild(css);
  parent.document.body.insertAdjacentHTML('afterbegin', html);
}

// ✨ Fireflies (behind chat)
if (!parent.document.querySelector('.firefly-layer')) {
  var html = '<div class="firefly-layer">';
  for (var i = 1; i <= 15; i++) {
    html += '<div class="firefly ff-' + i + '"></div>';
  }
  html += '</div>';

  var css = document.createElement('style');
  css.id = 'firefly-styles';
  css.textContent = ''
    + '.firefly-layer{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;overflow:hidden}'
    + '.firefly{position:absolute;border-radius:50%;pointer-events:none;'
    + 'background:radial-gradient(circle,rgba(255,230,150,0.95) 0%,rgba(255,200,80,0.4) 40%,transparent 70%);'
    + 'box-shadow:0 0 8px 2px rgba(255,210,100,0.3),0 0 20px 4px rgba(255,200,80,0.1)}'
    + '@keyframes ff-float{0%{transform:translate(0,0) scale(1);opacity:0}'
    + '15%{opacity:var(--bright)}30%{opacity:0.1}45%{opacity:var(--bright)}'
    + '60%{transform:translate(var(--mx),var(--my)) scale(0.8);opacity:0.15}'
    + '75%{opacity:var(--bright)}90%{opacity:0.1}'
    + '100%{transform:translate(var(--ex),var(--ey)) scale(1);opacity:0}}'
    + '.firefly{width:6px;height:6px;animation:ff-float var(--dur) ease-in-out infinite var(--del)}'
    + '.ff-1{top:15%;left:10%;--dur:8s;--del:0s;--mx:60px;--my:-40px;--ex:30px;--ey:20px;--bright:0.9}'
    + '.ff-2{top:30%;left:85%;--dur:10s;--del:1s;--mx:-50px;--my:30px;--ex:-80px;--ey:-10px;--bright:0.8}'
    + '.ff-3{top:60%;left:25%;--dur:12s;--del:2.5s;--mx:40px;--my:-60px;--ex:70px;--ey:-30px;--bright:0.7}'
    + '.ff-4{top:45%;left:55%;--dur:9s;--del:0.5s;--mx:-70px;--my:20px;--ex:-40px;--ey:50px;--bright:0.85}'
    + '.ff-5{top:80%;left:40%;--dur:11s;--del:3s;--mx:30px;--my:-50px;--ex:60px;--ey:-70px;--bright:0.75}'
    + '.ff-6{top:20%;left:70%;--dur:13s;--del:4s;--mx:-40px;--my:50px;--ex:-20px;--ey:30px;--bright:0.9}'
    + '.ff-7{top:70%;left:15%;--dur:8.5s;--del:1.5s;--mx:80px;--my:-20px;--ex:50px;--ey:10px;--bright:0.65}'
    + '.ff-8{top:50%;left:90%;--dur:10.5s;--del:2s;--mx:-60px;--my:-30px;--ex:-90px;--ey:20px;--bright:0.8}'
    + '.ff-9{top:10%;left:50%;--dur:14s;--del:5s;--mx:20px;--my:60px;--ex:40px;--ey:80px;--bright:0.7}'
    + '.ff-10{top:85%;left:65%;--dur:9.5s;--del:0.8s;--mx:-30px;--my:-70px;--ex:-50px;--ey:-40px;--bright:0.85}'
    + '.ff-11{top:35%;left:5%;--dur:11.5s;--del:3.5s;--mx:50px;--my:40px;--ex:90px;--ey:10px;--bright:0.75}'
    + '.ff-12{top:55%;left:75%;--dur:12.5s;--del:4.5s;--mx:-80px;--my:-10px;--ex:-60px;--ey:-50px;--bright:0.9}'
    + '.ff-13{top:25%;left:35%;--dur:7.5s;--del:1.2s;--mx:45px;--my:-35px;--ex:20px;--ey:40px;--bright:0.8}'
    + '.ff-14{top:75%;left:50%;--dur:10s;--del:2.8s;--mx:-25px;--my:55px;--ex:-70px;--ey:30px;--bright:0.7}'
    + '.ff-15{top:40%;left:20%;--dur:13.5s;--del:0.3s;--mx:70px;--my:15px;--ex:45px;--ey:-25px;--bright:0.85}'
  ;
  parent.document.head.appendChild(css);
  parent.document.body.insertAdjacentHTML('afterbegin', html);
}

// ❄ Snowfall (behind chat)
if (!parent.document.querySelector('.snow-layer')) {
  var html = '';
  html += '<div class="frost-frame frost-top"></div>';
  html += '<div class="frost-frame frost-bottom"></div>';
  html += '<div class="frost-frame frost-left"></div>';
  html += '<div class="frost-frame frost-right"></div>';
  html += '<div class="snow-layer">';
  for (var i = 1; i <= 20; i++) {
    var sc = i % 3 === 0 ? 'flake-lg' : (i % 3 === 1 ? 'flake-md' : 'flake-sm');
    html += '<div class="snowflake ' + sc + ' flake-' + i + '"></div>';
  }
  html += '</div>';

  var css = document.createElement('style');
  css.id = 'snow-styles';
  css.textContent = ''
    + '.snow-layer{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;overflow:hidden}'
    + '.snowflake{position:absolute;top:-20px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,0.95) 0%,rgba(220,230,255,0.6) 40%,rgba(200,215,255,0.0) 100%);pointer-events:none;filter:blur(0.5px)}'
    + '.flake-lg{width:8px;height:8px;box-shadow:0 0 6px 1px rgba(200,220,255,0.4)}'
    + '.flake-md{width:5px;height:5px;box-shadow:0 0 4px 1px rgba(200,220,255,0.3)}'
    + '.flake-sm{width:3px;height:3px;box-shadow:0 0 3px 1px rgba(200,220,255,0.2)}'
    + '.frost-frame{position:fixed;pointer-events:none;z-index:0}'
    + '.frost-top{top:0;left:0;right:0;height:40px;background:linear-gradient(to bottom,rgba(180,210,255,0.08),transparent)}'
    + '.frost-bottom{bottom:0;left:0;right:0;height:40px;background:linear-gradient(to top,rgba(180,210,255,0.08),transparent)}'
    + '.frost-left{top:0;left:0;bottom:0;width:30px;background:linear-gradient(to right,rgba(180,210,255,0.06),transparent)}'
    + '.frost-right{top:0;right:0;bottom:0;width:30px;background:linear-gradient(to left,rgba(180,210,255,0.06),transparent)}'
    + '@keyframes snowfall{0%{transform:translateY(-20px) translateX(0) rotate(0deg);opacity:0}10%{opacity:1}90%{opacity:0.8}100%{transform:translateY(105vh) translateX(var(--drift)) rotate(360deg);opacity:0}}'
    + '.flake-1{left:3%;animation:snowfall 8s linear infinite 0s;--drift:30px}'
    + '.flake-2{left:8%;animation:snowfall 12s linear infinite 1s;--drift:-20px}'
    + '.flake-3{left:14%;animation:snowfall 10s linear infinite 3s;--drift:25px}'
    + '.flake-4{left:20%;animation:snowfall 9s linear infinite 0.5s;--drift:-35px}'
    + '.flake-5{left:26%;animation:snowfall 14s linear infinite 2s;--drift:15px}'
    + '.flake-6{left:32%;animation:snowfall 11s linear infinite 4s;--drift:-25px}'
    + '.flake-7{left:38%;animation:snowfall 8.5s linear infinite 1.5s;--drift:40px}'
    + '.flake-8{left:44%;animation:snowfall 13s linear infinite 3.5s;--drift:-15px}'
    + '.flake-9{left:50%;animation:snowfall 9.5s linear infinite 0.8s;--drift:20px}'
    + '.flake-10{left:55%;animation:snowfall 11.5s linear infinite 2.5s;--drift:-30px}'
    + '.flake-11{left:60%;animation:snowfall 10.5s linear infinite 4.5s;--drift:35px}'
    + '.flake-12{left:65%;animation:snowfall 8s linear infinite 1.2s;--drift:-20px}'
    + '.flake-13{left:70%;animation:snowfall 12.5s linear infinite 3.2s;--drift:25px}'
    + '.flake-14{left:76%;animation:snowfall 9s linear infinite 0.3s;--drift:-40px}'
    + '.flake-15{left:82%;animation:snowfall 13.5s linear infinite 2.8s;--drift:15px}'
    + '.flake-16{left:87%;animation:snowfall 10s linear infinite 5s;--drift:-25px}'
    + '.flake-17{left:91%;animation:snowfall 11s linear infinite 1.8s;--drift:30px}'
    + '.flake-18{left:94%;animation:snowfall 8.5s linear infinite 3.8s;--drift:-15px}'
    + '.flake-19{left:97%;animation:snowfall 12s linear infinite 0.6s;--drift:20px}'
    + '.flake-20{left:5%;animation:snowfall 14.5s linear infinite 4.2s;--drift:-35px}'
  ;
  parent.document.head.appendChild(css);
  parent.document.body.insertAdjacentHTML('afterbegin', html);
}

// 🌫 Fog (behind chat)
if (!parent.document.querySelector('.fog-layer')) {
  var html = '<div class="fog-layer">';
  html += '<div class="fog-bank fog-1"></div>';
  html += '<div class="fog-bank fog-2"></div>';
  html += '<div class="fog-bank fog-3"></div>';
  html += '<div class="fog-bank fog-4"></div>';
  html += '<div class="fog-bank fog-5"></div>';
  html += '<div class="fog-wisp wisp-1"></div>';
  html += '<div class="fog-wisp wisp-2"></div>';
  html += '<div class="fog-wisp wisp-3"></div>';
  html += '</div>';

  var css = document.createElement('style');
  css.id = 'fog-styles';
  css.textContent = ''
    + '.fog-layer{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1;overflow:hidden}'
    + '.fog-bank{position:absolute;pointer-events:none;border-radius:50%;filter:blur(60px)}'
    + '.fog-1{bottom:-20%;left:-10%;width:120%;height:45%;'
    + 'background:radial-gradient(ellipse at center,rgba(180,185,195,0.18) 0%,rgba(160,168,180,0.08) 40%,transparent 70%);'
    + 'animation:fog-drift-slow 25s ease-in-out infinite alternate}'
    + '.fog-2{bottom:5%;left:-20%;width:140%;height:35%;'
    + 'background:radial-gradient(ellipse at 30% 50%,rgba(175,180,190,0.14) 0%,rgba(165,172,182,0.06) 45%,transparent 70%);'
    + 'animation:fog-drift-mid 30s ease-in-out infinite alternate-reverse}'
    + '.fog-3{top:15%;left:-15%;width:130%;height:40%;'
    + 'background:radial-gradient(ellipse at 60% 50%,rgba(185,190,200,0.1) 0%,rgba(170,178,188,0.04) 50%,transparent 70%);'
    + 'animation:fog-drift-slow 35s ease-in-out infinite alternate}'
    + '.fog-4{bottom:10%;right:-15%;width:60%;height:50%;'
    + 'background:radial-gradient(ellipse at 40% 60%,rgba(178,183,193,0.12) 0%,transparent 65%);'
    + 'animation:fog-drift-right 28s ease-in-out infinite alternate}'
    + '.fog-5{top:30%;left:-10%;width:55%;height:45%;'
    + 'background:radial-gradient(ellipse at 60% 40%,rgba(172,178,190,0.1) 0%,transparent 60%);'
    + 'animation:fog-drift-left 32s ease-in-out infinite alternate-reverse}'
    + '.fog-wisp{position:absolute;pointer-events:none;border-radius:50%;filter:blur(40px)}'
    + '.wisp-1{top:20%;left:10%;width:35%;height:15%;'
    + 'background:radial-gradient(ellipse,rgba(190,195,205,0.09) 0%,transparent 70%);'
    + 'animation:wisp-float 18s ease-in-out infinite alternate}'
    + '.wisp-2{top:50%;right:5%;width:30%;height:12%;'
    + 'background:radial-gradient(ellipse,rgba(185,190,200,0.07) 0%,transparent 70%);'
    + 'animation:wisp-float 22s ease-in-out infinite alternate-reverse}'
    + '.wisp-3{bottom:25%;left:25%;width:40%;height:10%;'
    + 'background:radial-gradient(ellipse,rgba(180,186,196,0.08) 0%,transparent 70%);'
    + 'animation:wisp-float 15s ease-in-out infinite alternate}'
    + '@keyframes fog-drift-slow{0%{transform:translateX(0) scale(1)}100%{transform:translateX(40px) scale(1.05)}}'
    + '@keyframes fog-drift-mid{0%{transform:translateX(0) scale(1)}100%{transform:translateX(-50px) scale(1.03)}}'
    + '@keyframes fog-drift-right{0%{transform:translateX(0) scaleX(1)}100%{transform:translateX(-35px) scaleX(1.1)}}'
    + '@keyframes fog-drift-left{0%{transform:translateX(0) scaleX(1)}100%{transform:translateX(45px) scaleX(1.08)}}'
    + '@keyframes wisp-float{0%{transform:translateX(0) translateY(0);opacity:0.6}50%{opacity:1}100%{transform:translateX(30px) translateY(-15px);opacity:0.5}}'
  ;
  parent.document.head.appendChild(css);
  parent.document.body.insertAdjacentHTML('afterbegin', html);
}
